t.script:
(function () {
  var root = document.getElementById('s'), key = root.getAttribute('data-k'), q = document.getElementById('q'), box = document.getElementById('box'), res = document.getElementById('res');
  var up = window.parent, here = location.origin, state = 0, tok = null, timer = null, seq = 0;
  function say(m) { m.smb = 1; if (up !== window) { up.postMessage(m, here); } }
  function size() { say({ h: Math.ceil(root.getBoundingClientRect().height) + 2 }); }
  function shut() { box.hidden = true; res.textContent = ''; size(); }
  if (!key) { say({ off: 1 }); return; }
  window.gm_authFailure = function () { say({ off: 1 }); };
  window.smbG = function () { google.maps.importLibrary('places').then(function () { state = 2; ask(); }, function () { say({ off: 1 }); }); };
  function load() {
    if (state) { return; } state = 1;
    var sc = document.createElement('script');
    sc.src = 'https://maps.googleapis.com/maps/api/js?key=' + encodeURIComponent(key) + '&loading=async&libraries=places&region=LB&callback=smbG';
    sc.onerror = function () { say({ off: 1 }); };
    document.head.appendChild(sc);
  }
  function ask() {
    var v = q.value.trim(), mine = ++seq;
    if (state !== 2 || v.length < 3) { if (v.length < 3) { shut(); } return; }
    var P = google.maps.places;
    if (!tok) { tok = new P.AutocompleteSessionToken(); }
    P.AutocompleteSuggestion.fetchAutocompleteSuggestions({ input: v, sessionToken: tok, includedRegionCodes: ['lb'] }).then(function (r) {
      if (mine !== seq) { return; }
      res.textContent = '';
      var list = (r.suggestions || []).filter(function (s) { return s.placePrediction; }).slice(0, 5);
      list.forEach(function (s) {
        var p = s.placePrediction, b = document.createElement('button'), sm = document.createElement('small');
        b.type = 'button'; b.className = 'r';
        b.textContent = p.mainText ? p.mainText.text : p.text.text;
        sm.textContent = p.secondaryText ? p.secondaryText.text : ''; b.appendChild(sm);
        b.addEventListener('click', function () {
          q.value = p.text.text; q.blur(); shut();
          p.toPlace().fetchFields({ fields: ['location'] }).then(function (d) {
            tok = null;
            var l = d.place.location; if (l) { say({ lat: l.lat(), lng: l.lng() }); }
          }, function () { tok = null; });
        });
        res.appendChild(b);
      });
      if (!list.length) { var n = document.createElement('div'); n.className = 'n'; n.textContent = 'No match. Try another name, or move the map to your door.'; res.appendChild(n); }
      box.hidden = false; size();
    }, function () { if (mine === seq) { shut(); } });
  }
  q.addEventListener('focus', load);
  q.addEventListener('input', function () { load(); clearTimeout(timer); timer = setTimeout(ask, 350); });
  q.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); var f = res.querySelector('.r'); if (f) { f.click(); } } });
  size();
})();

(function () {
  var el = document.getElementById('map'); if (!el || !window.L) { return; }
  var lat = parseFloat(el.getAttribute('data-lat')), lng = parseFloat(el.getAttribute('data-lng')), has = !isNaN(lat) && !isNaN(lng);
  var map = L.map(el, { zoomControl: true }).setView(has ? [lat, lng] : [33.89, 35.55], has ? 17 : 9);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '&copy; OpenStreetMap contributors' }).addTo(map);
  var pin = L.marker(map.getCenter(), { draggable: true }).addTo(map), moved = has;
  var good = document.getElementById('good'), bad = document.getElementById('bad'), save = document.getElementById('save'), me = document.getElementById('me');
  function fail(t) { bad.textContent = t; bad.hidden = false; }
  function touched() { moved = true; good.hidden = true; bad.hidden = true; }
  map.on('move', function () { pin.setLatLng(map.getCenter()); });
  map.on('dragstart zoomstart', touched);
  pin.on('dragend', function () { touched(); map.panTo(pin.getLatLng()); });
  map.on('click', function (e) { touched(); map.panTo(e.latlng); });
  /* 28 Nov 2026: the Google search frame above the map tells us its height, a chosen place, or that it cannot work */
  var sw = document.getElementById('sw'), sf = document.getElementById('sf'), hint = document.querySelector('.hint');
  if (sf) {
    window.addEventListener('message', function (e) {
      var m = e.data; if (e.origin !== location.origin || e.source !== sf.contentWindow || !m || m.smb !== 1) { return; }
      if (m.off) { sw.hidden = true; return; }
      if (m.h) { sf.style.height = Math.max(50, Math.min(420, m.h)) + 'px'; }
      if (typeof m.lat === 'number' && typeof m.lng === 'number') {
        touched(); map.setView([m.lat, m.lng], 17);
        if (hint) { hint.textContent = 'Now move the map so the pin sits exactly on your door, then save.'; }
      }
    });
  }
  /* 26 Nov 2026: say why the phone gave no position (blocked for the site, switched off, or too slow) and, when the
     precise fix fails, try once more with the quick network position before giving up */
  var why = { 1: 'Location is blocked for this site. Tap the lock icon next to the address bar, allow Location, then try again. Or drag the map to your door.',
              2: 'Your phone could not find its position. Turn on Location (GPS) and try again, or drag the map to your door.',
              3: 'Finding your position took too long. Try again, or drag the map to your door.' };
  function locate(precise) {
    navigator.geolocation.getCurrentPosition(function (p) { me.disabled = false; me.textContent = 'Use my current location'; touched(); map.setView([p.coords.latitude, p.coords.longitude], 18); },
      function (e) { if (precise && e.code !== 1) { locate(false); return; } me.disabled = false; me.textContent = 'Use my current location'; fail(why[e.code] || why[2]); },
      precise ? { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 } : { enableHighAccuracy: false, timeout: 15000, maximumAge: 300000 });
  }
  me.addEventListener('click', function () {
    if (!navigator.geolocation) { fail(why[2]); return; }
    me.disabled = true; me.textContent = 'Finding your location…'; bad.hidden = true; locate(true);
  });
  save.addEventListener('click', function () {
    var c = map.getCenter();
    if (!moved || map.getZoom() < 15) { fail('Please zoom in and place the pin on your door first.'); return; }
    if (c.lat < 33.0 || c.lat > 34.75 || c.lng < 35.0 || c.lng > 36.7) { fail('We deliver in Lebanon only. Please place the pin in Lebanon.'); return; }
    var fd = new FormData();
    fd.append('csrf_token', el.getAttribute('data-c')); fd.append('x_name', 'pin'); fd.append('x_order', el.getAttribute('data-o')); fd.append('x_token', el.getAttribute('data-t'));
    fd.append('x_lat', c.lat.toFixed(7)); fd.append('x_lng', c.lng.toFixed(7));
    save.disabled = true; bad.hidden = true;
    fetch('/website/form/x_location_pin', { method: 'POST', body: fd })
      .then(function (r) { return r.json(); })
      .then(function (j) { if (!j || !j.id) { throw new Error('no id'); } save.disabled = false; good.hidden = false; })
      .catch(function () { save.disabled = false; fail('Could not save. Please check your connection and try again.'); });
  });
})();
